+        (err: unknown) => {
+          assert.ok(err instanceof Error);
+          assert.match(err.message, /https:\/\/example\.com\/missing\.json/);
+          assert.match(err.message, /404/);
+          return true;
+        },
+      );
+    } finally {
+      mock.restoreAll();
+    }
+  });
+
+  it("throws a descriptive error when the response body is invalid JSON", async () => {
